const crypto = require('node:crypto');
const { promisify } = require('node:util');
const express = require('express');
const session = require('express-session');

const scrypt = promisify(crypto.scrypt);

// --- password hashing (stdlib scrypt, stored as "salt:key" hex) ---

async function hashPassword(password) {
  const salt = crypto.randomBytes(16);
  const key = await scrypt(password, salt, 64);
  return `${salt.toString('hex')}:${key.toString('hex')}`;
}

async function verifyPassword(password, stored) {
  const [salt, key] = stored.split(':').map((h) => Buffer.from(h, 'hex'));
  return crypto.timingSafeEqual(key, await scrypt(password, salt, 64));
}

// Verified against when the user doesn't exist, so response time doesn't leak which usernames are real.
const dummyHash = hashPassword(crypto.randomBytes(16).toString('hex'));

// ponytail: users live in memory. Swap for a DB lookup; nothing else here changes.
const users = new Map(); // username -> { hash }

// --- rate limiting: 5 failed attempts per 15 min, per IP and per username ---

const MAX_FAILS = 5;
const WINDOW_MS = 15 * 60 * 1000;

// ponytail: in-process Map, single instance only. Move this and the session store to Redis for a second instance.
const attempts = new Map(); // key -> { count, resetAt }

// Counts the attempt up front (refunded on success) so parallel requests can't all slip past the check.
function countAttempt(key, now = Date.now()) {
  let a = attempts.get(key);
  if (!a || a.resetAt <= now) attempts.set(key, (a = { count: 0, resetAt: now + WINDOW_MS }));
  a.count++;
  return a;
}

setInterval(() => {
  const now = Date.now();
  for (const [key, a] of attempts) if (a.resetAt <= now) attempts.delete(key);
}, WINDOW_MS).unref();

// --- app ---

const app = express();
// Behind a reverse proxy, set app.set('trust proxy', 1) or req.ip is the proxy and secure cookies won't be sent.
app.use(express.json());
app.use(
  session({
    // Random per boot is fine while sessions are in memory (they die on restart anyway).
    secret: process.env.SESSION_SECRET ?? crypto.randomBytes(32).toString('hex'),
    resave: false,
    saveUninitialized: false,
    cookie: {
      httpOnly: true,
      sameSite: 'lax',
      secure: process.env.NODE_ENV === 'production',
      maxAge: 24 * 60 * 60 * 1000,
    },
  }),
);

app.post('/login', async (req, res, next) => {
  const { username, password } = req.body ?? {};
  if (
    typeof username !== 'string' || typeof password !== 'string' ||
    !username || !password || username.length > 256 || password.length > 1024
  ) {
    return res.status(400).json({ error: 'username and password required' });
  }
  const name = username.toLowerCase();

  const counted = [countAttempt(`ip:${req.ip}`), countAttempt(`user:${name}`)];
  const limited = counted.filter((a) => a.count > MAX_FAILS);
  if (limited.length) {
    const retryMs = Math.max(...limited.map((a) => a.resetAt)) - Date.now();
    res.set('Retry-After', String(Math.ceil(retryMs / 1000)));
    return res.status(429).json({ error: 'too many failed attempts, try again later' });
  }

  const user = users.get(name);
  const passwordOk = await verifyPassword(password, user?.hash ?? (await dummyHash));
  if (!user || !passwordOk) return res.status(401).json({ error: 'invalid credentials' });

  counted.forEach((a) => a.count--); // success doesn't count against the limit
  // New session id on login prevents session fixation.
  req.session.regenerate((err) => {
    if (err) return next(err);
    req.session.user = name;
    res.json({ user: name });
  });
});

app.post('/logout', (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie('connect.sid').json({ ok: true });
  });
});

function requireLogin(req, res, next) {
  if (!req.session.user) return res.status(401).json({ error: 'not logged in' });
  next();
}

app.get('/me', requireLogin, (req, res) => res.json({ user: req.session.user }));

module.exports = { app, users, hashPassword };

if (require.main === module) {
  app.listen(3000, () => console.log('listening on http://localhost:3000'));
}

const test = require('node:test');
const assert = require('node:assert');
const { app, users, hashPassword } = require('./app');

test('login, session, rate limit', async () => {
  users.set('alice', { hash: await hashPassword('correct horse') });
  assert.ok(!users.get('alice').hash.includes('correct horse'));

  const server = app.listen(0);
  const url = `http://localhost:${server.address().port}`;
  const login = (password, username = 'alice') =>
    fetch(`${url}/login`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ username, password }),
    });

  try {
    assert.strictEqual((await fetch(`${url}/me`)).status, 401);
    assert.strictEqual((await login(undefined)).status, 400);

    const ok = await login('correct horse');
    assert.strictEqual(ok.status, 200);
    const cookie = ok.headers.get('set-cookie').split(';')[0];
    const me = await fetch(`${url}/me`, { headers: { cookie } });
    assert.deepStrictEqual(await me.json(), { user: 'alice' });

    await fetch(`${url}/logout`, { method: 'POST', headers: { cookie } });
    assert.strictEqual((await fetch(`${url}/me`, { headers: { cookie } })).status, 401);

    assert.strictEqual((await login('x', 'nobody')).status, 401);
    // 1 bad request + 1 unknown user above + 3 here = 5 failures from this IP
    for (let i = 0; i < 3; i++) assert.strictEqual((await login('wrong')).status, 401);

    const blocked = await login('correct horse');
    assert.strictEqual(blocked.status, 429);
    assert.ok(Number(blocked.headers.get('retry-after')) > 0);
  } finally {
    server.close();
  }
});

